    // Faster I/O for competitive programming
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    // Read the size of the array
    if (!(cin >> n)) return 0; // No input
    if (n == 0) {
        // Edge case: empty array -> maximum subarray sum is 0
        cout << 0 << '\n';
        return 0;
    }

    long long current_max, global_max; // Use long long to avoid overflow
    long long x;

    // Initialize with the first element
    cin >> x;
    current_max = global_max = x;

    // Kadane's algorithm: process remaining elements
    for (int i = 1; i < n; ++i) {
        cin >> x;
        // Either start a new subarray at x or extend the previous one
        current_max = max(x, current_max + x);
        // Update the global maximum
        global_max = max(global_max, current_max);
    }

    // Output the maximum subarray sum
    cout << global_max << '\n';
    return 0;
}
