#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    // Kadane's algorithm for maximum subarray sum
    long long max_sum;          // overall maximum subarray sum
    long long current_sum;      // maximum sum of subarray ending at current position
    bool first = true;          // flag to handle the first element
    long long x;

    // Read all integers from input until EOF
    while (cin >> x) {
        if (first) {
            // First element initializes both current_sum and max_sum
            current_sum = x;
            max_sum = x;
            first = false;
        } else {
            // Update current_sum: either start new subarray at x or extend previous
            current_sum = max(x, current_sum + x);
            // Update overall maximum
            max_sum = max(max_sum, current_sum);
        }
    }

    // Handle empty input (no numbers)
    if (first) {
        cout << 0 << endl;
    } else {
        cout << max_sum << endl;
    }

    return 0;
}
