#include <iostream>
#include <algorithm>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Read the number of elements in the array.
    long long n;
    if (!(std::cin >> n)) {
        // No input provided.
        std::cout << 0;
        return 0;
    }

    // Handle empty array.
    if (n == 0) {
        std::cout << 0;
        return 0;
    }

    // Read the first element to initialise Kadane's variables.
    long long first;
    if (!(std::cin >> first)) {
        // Expected at least one element but none were given.
        std::cout << 0;
        return 0;
    }

    long long max_ending_here = first; // Maximum sum of subarray ending at current position.
    long long max_so_far = first;      // Overall maximum subarray sum found so far.

    bool sufficient_input = true;
    // Process the remaining n-1 elements.
    for (long long i = 1; i < n; ++i) {
        long long val;
        if (!(std::cin >> val)) {
            // Input ended prematurely; we cannot guarantee correctness.
            sufficient_input = false;
            break;
        }
        // Either extend the previous subarray or start a new one at current element.
        max_ending_here = std::max(val, max_ending_here + val);
        // Update the global maximum if needed.
        if (max_ending_here > max_so_far) {
            max_so_far = max_ending_here;
        }
    }

    // Output the result only if we successfully read all expected numbers.
    if (sufficient_input) {
        std::cout << max_so_far;
    } else {
        // Incomplete input: defined behaviour is to return 0.
        std::cout << 0;
    }

    return 0;
}

