    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    if (n <= 0) {
        cout << 0 << endl;
        return 0;
    }

    long long max_ending_here = 0;
    long long max_so_far = LLONG_MIN;

    for (int i = 0; i < n; i++) {
        long long x;
        cin >> x;

        if (max_ending_here < 0) {
            max_ending_here = x;
        } else {
            max_ending_here += x;
        }

        max_so_far = max(max_so_far, max_ending_here);
    }

    cout << max_so_far << endl;

    return 0;
}
